{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    # Build maps
    node_map = {}
    children_map = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children_map.setdefault(n['parent'], []).append(nid)
    # Initially all nodes retained
    retained = set(node_map.keys())
    removed = []
    # Sort nodes by depth descending, then id ascending for tie-break
    sorted_nodes = sorted(nodes, key=lambda x: (-x['depth'], x['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue  # already removed
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols or nid == 'root':
            continue
        # Check if any child is still retained
        has_retained_child = False
        for cid in children_map.get(nid, []):
            if cid in retained:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        # Tentatively remove this node (and its subtree, but subtree already empty)
        # Check if all required symbols still represented without this node
        retained_without = retained - {nid}
        # Also need to consider symbols from nodes that would be removed with it? Actually its children are already gone
        # So just check remaining symbols
        req_symbols_covered = True
        for sym in required_symbols:
            found = False
            for rid in retained_without:
                if node_map[rid]['symbol'] == sym:
                    found = True
                    break
            if not found:
                req_symbols_covered = False
                break
        if req_symbols_covered:
            retained = retained_without
            removed.append(nid)
    # After processing, sort retained ids
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"
}
